  1224	    if ( matvar->compression == MAT_COMPRESSION_ZLIB ) {
  1225	#if defined(HAVE_ZLIB)
  1226	        mat_uint32_t uncomp_buf[16] = {0,};
  1227	        int nbytes;
  1228	        mat_uint32_t array_flags, len;
  1229	
  1230	        /* Field name length */
  1231	        bytesread += InflateVarTag(mat,matvar,uncomp_buf);
  1232	        if ( mat->byteswap ) {
  1233	            (void)Mat_uint32Swap(uncomp_buf);
  1234	            (void)Mat_uint32Swap(uncomp_buf+1);
  1235	        }
  1236	        if ( (uncomp_buf[0] & 0x0000ffff) == MAT_T_INT32 && uncomp_buf[1] > 0 ) {
  1237	            fieldname_size = uncomp_buf[1];
  1238	        } else {
  1239	            Mat_Critical("Error getting fieldname size");
  1240	            return bytesread;
  1241	        }
  1242	
  1243	        /* Field name tag */
  1244	        bytesread += InflateVarTag(mat,matvar,uncomp_buf);
  1245	        if ( mat->byteswap )
  1246	            (void)Mat_uint32Swap(uncomp_buf);
  1247	        /* Name of field */
  1248	        if ( uncomp_buf[0] == MAT_T_INT8 ) {    /* Name not in tag */
  1249	            if ( mat->byteswap )
  1250	                len = Mat_uint32Swap(uncomp_buf+1);
  1251	            else
  1252	                len = uncomp_buf[1];
  1253	            nfields = len / fieldname_size;
  1254	            if ( nfields*fieldname_size % 8 != 0 )
  1255	                i = 8-(nfields*fieldname_size % 8);
  1256	            else
  1257	                i = 0;
  1258	            if ( nfields ) {
  1259	                char *ptr = (char*)malloc(nfields*fieldname_size+i);
  1260	                if ( NULL != ptr ) {
  1261	                    bytesread += InflateVarName(mat,matvar,ptr,nfields*fieldname_size+i);
  1262	                    SetFieldNames(matvar, ptr, nfields, fieldname_size);
  1263	                    free(ptr);
  1264	                }
  1265	            } else {
  1266	                matvar->internal->num_fields = 0;
  1267	                matvar->internal->fieldnames = NULL;
  1268	            }
  1269	        } else {
  1270	            len = (uncomp_buf[0] & 0xffff0000) >> 16;
  1271	            if ( ((uncomp_buf[0] & 0x0000ffff) == MAT_T_INT8) && len > 0 && len <= 4 ) {
  1272	                /* Name packed in tag */
  1273	                nfields = len / fieldname_size;
  1274	                if ( nfields ) {
  1275	                    SetFieldNames(matvar, (char*)(uncomp_buf + 1), nfields, fieldname_size);
  1276	                } else {
