  1306	        for ( i = 0; i < nelems; i++ ) {
  1307	            size_t k;
  1308	            for ( k = 0; k < nfields; k++ ) {
  1309	                fields[i*nfields+k] = Mat_VarCalloc();
  1310	            }
  1311	        }
