  1318	                    }
  1319	                }
  1320	            }
  1321	        }
  1322	
  1323	        for ( i = 0; i < nelems_x_nfields; i++ ) {
  1324	            /* Read variable tag for struct field */
  1325	            bytesread += InflateVarTag(mat,matvar,uncomp_buf);
  1326	            if ( mat->byteswap ) {
  1327	                (void)Mat_uint32Swap(uncomp_buf);
  1328	                (void)Mat_uint32Swap(uncomp_buf+1);
  1329	            }
  1330	            nbytes = uncomp_buf[1];
