  1344	            nbytes -= 16;
  1345	            if ( mat->byteswap ) {
  1346	                (void)Mat_uint32Swap(uncomp_buf);
  1347	                (void)Mat_uint32Swap(uncomp_buf+1);
  1348	                (void)Mat_uint32Swap(uncomp_buf+2);
  1349	                (void)Mat_uint32Swap(uncomp_buf+3);
