  1352	            if ( uncomp_buf[0] == MAT_T_UINT32 ) {
  1353	               array_flags = uncomp_buf[2];
  1354	               fields[i]->class_type = CLASS_FROM_ARRAY_FLAGS(array_flags);
  1355	               fields[i]->isComplex  = (array_flags & MAT_F_COMPLEX);
