  1383	                    fields[i]->rank = uncomp_buf[1];
  1384	                    nbytes -= fields[i]->rank;
  1385	                    fields[i]->rank /= 4;
  1386	                    fields[i]->dims = (size_t*)malloc(fields[i]->rank*
  1387	                                             sizeof(*fields[i]->dims));
