  1389	                        for ( j = 0; j < fields[i]->rank; j++ )
  1390	                            fields[i]->dims[j] = Mat_uint32Swap(dims+j);
  1391	                    } else {
  1392	                        for ( j = 0; j < fields[i]->rank; j++ )
  1393	                            fields[i]->dims[j] = dims[j];
  1394	                    }
  1395	                    if ( fields[i]->rank % 2 != 0 )
  1396	                        nbytes -= 4;
  1397	                }
  1398	                if ( do_clean )
  1399	                    free(dims);
