  1401	                bytesread += InflateVarTag(mat,matvar,uncomp_buf);
  1402	                nbytes -= 8;
  1403	                fields[i]->internal->z = (z_streamp)calloc(1,sizeof(z_stream));
  1404	                if ( fields[i]->internal->z != NULL ) {
  1405	                    err = inflateCopy(fields[i]->internal->z,matvar->internal->z);
  1406	                    if ( err == Z_OK ) {
  1407	                        fields[i]->internal->datapos = ftell((FILE*)mat->fp);
  1408	                        if ( fields[i]->internal->datapos != -1L ) {
  1409	                            fields[i]->internal->datapos -= matvar->internal->z->avail_in;
  1410	                            if ( fields[i]->class_type == MAT_C_STRUCT )
  1411	                                bytesread+=ReadNextStructField(mat,fields[i]);
  1412	                            else if ( fields[i]->class_type == MAT_C_CELL )
  1413	                                bytesread+=ReadNextCell(mat,fields[i]);
