  1415	                                /* Memory optimization: Read data if less in size
  1416	                                   than the zlib inflate state (approximately) */
  1417	                                err = Mat_VarRead5(mat,fields[i]);
  1418	                                fields[i]->internal->data = fields[i]->data;
  1419	                                fields[i]->data = NULL;
